import re
import shutil
import tempfile
from pathlib import Path


class TemporaryPlantFileStorage:
    """Private process-local file store. Keys are generated by the domain service."""

    _KEY_PATTERN = re.compile(r"^[A-Za-z0-9_-]{1,100}$")

    def __init__(self) -> None:
        self._root = Path(tempfile.mkdtemp(prefix="roomflow-plants-")).resolve()

    def save(self, storage_key: str, content: bytes) -> None:
        path = self._path_for(storage_key)
        temp_path = path.with_suffix(".tmp")
        try:
            temp_path.write_bytes(content)
            temp_path.replace(path)
        finally:
            temp_path.unlink(missing_ok=True)

    def read(self, storage_key: str) -> bytes | None:
        path = self._path_for(storage_key)
        return path.read_bytes() if path.is_file() else None

    def delete(self, storage_key: str) -> None:
        path = self._path_for(storage_key)
        path.unlink(missing_ok=True)

    def close(self) -> None:
        """Remove this process-local temporary store when its runtime is released."""
        shutil.rmtree(self._root, ignore_errors=True)

    def __del__(self) -> None:
        try:
            self.close()
        except Exception:
            pass

    def _path_for(self, storage_key: str) -> Path:
        if not self._KEY_PATTERN.fullmatch(storage_key):
            raise ValueError("Identificador de arquivo inválido.")
        path = (self._root / storage_key).resolve()
        if path.parent != self._root:
            raise ValueError("Caminho de arquivo inválido.")
        return path
